function o(t){return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:2}).format(t)}function u(t=new Date){return t.toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric",year:"numeric"})}function n(t,e){return Math.round(t*e*100)/100}function a(t){return Math.round(t.reduce((e,r)=>e+n(r.qty,r.unitPrice),0)*100)/100}export{o as a,u as b,n as c,a as d};
